/* ==========================================================================
   BI Ergonomia - ElevaLife
   DIAGRAMAS CORPORAIS (frente/costas) - baseados em imagem anatomica
   licenciada (fundo removido, PNG com alpha, embutida em base64 para o
   Artifact publicado ser 100% self-contained). Sobre a imagem, o mesmo
   mecanismo de caixa tracejada + linha-guia por regiao (inalterado),
   mostrando o valor (dias perdidos em Med Ocup, contagem de restricoes em
   Compativeis).

   Convencao anatomica (a pessoa olhando para o espectador na frente, de
   costas para o espectador atras): regiao "Direita/Direito" e o lado
   DIREITO da PESSOA.
   - Frente: pessoa de frente -> lado D da pessoa fica a ESQUERDA da imagem.
   - Costas: pessoa de costas -> lado D da pessoa fica a DIREITA da imagem.
   ========================================================================== */

(function (global) {
  "use strict";

  // ------------------------------------------------------------------
  // Layout: imagem central (380x869) + duas colunas de rotulo (esq/dir).
  // ------------------------------------------------------------------
  // Caixa da legenda aumentada (era 96x32) - pedido do Leo pra deixar a
  // fonte da legenda (nome da regiao + valor) maior e mais legivel dentro
  // da caixa pontilhada.
  const LARGURA_CAIXA = 112;
  const ALTURA_CAIXA = 38;
  const GAP = 14;
  const X_COLUNA_ESQ = 6;

  const IMG_W = 380;
  const IMG_H = 869;
  const IMG_X = X_COLUNA_ESQ + LARGURA_CAIXA + GAP; // 116
  const IMG_Y = 8;

  const X_COLUNA_DIR = IMG_X + IMG_W + GAP; // 510
  const W = X_COLUNA_DIR + LARGURA_CAIXA + 6; // 612
  const H = IMG_H + IMG_Y * 2; // 885

  // Imagens-base (fundo removido), embutidas para a pagina publicada ser
  // autocontida (hosts externos de imagem sao bloqueados no Artifact).
  const IMG_FRENTE = "data:image/png;base64,";
  const IMG_COSTAS = "data:image/png;base64,";

  // ------------------------------------------------------------------
  // Pontos de fixacao (rotulo) por regiao - coordenadas medidas
  // diretamente sobre a imagem-base (landmarks anatomicos reais) - e
  // coluna/posicao onde a caixa de rotulo fica.
  // ------------------------------------------------------------------
  const CONFIG_FRENTE = [
    { regiao: "Ombro Direito", corpo: [IMG_X + 87, IMG_Y + 170], caixa: "esq", y: 162 },
    { regiao: "Ombro Esquerdo", corpo: [IMG_X + 292, IMG_Y + 170], caixa: "dir", y: 162 },
    { regiao: "Cotovelo Direito", corpo: [IMG_X + 83, IMG_Y + 304], caixa: "esq", y: 297 },
    { regiao: "Cotovelo Esquerdo", corpo: [IMG_X + 297, IMG_Y + 306], caixa: "dir", y: 297 },
    { regiao: "Punho Direito", corpo: [IMG_X + 70, IMG_Y + 419], caixa: "esq", y: 387 },
    { regiao: "Punho Esquerdo", corpo: [IMG_X + 311, IMG_Y + 419], caixa: "dir", y: 387 },
    { regiao: "Mao Direita", corpo: [IMG_X + 52, IMG_Y + 448], caixa: "esq", y: 451 },
    { regiao: "Mao Esquerda", corpo: [IMG_X + 327, IMG_Y + 448], caixa: "dir", y: 451 },
    { regiao: "Pe Direito", corpo: [IMG_X + 172, IMG_Y + 813], caixa: "esq", y: 805 },
    { regiao: "Pe Esquerdo", corpo: [IMG_X + 233, IMG_Y + 813], caixa: "dir", y: 805 },
  ];

  const CONFIG_COSTAS = [
    { regiao: "Cervical", corpo: [IMG_X + 183, IMG_Y + 130], caixa: "esq", y: 122 },
    { regiao: "Dorsal", corpo: [IMG_X + 183, IMG_Y + 243], caixa: "dir", y: 235 },
    { regiao: "Lombar", corpo: [IMG_X + 183, IMG_Y + 374], caixa: "esq", y: 366 },
    { regiao: "Quadril Direito", corpo: [IMG_X + 222, IMG_Y + 426], caixa: "dir", y: 418 },
    { regiao: "Quadril Esquerdo", corpo: [IMG_X + 139, IMG_Y + 435], caixa: "esq", y: 427 },
    { regiao: "Joelho Direito", corpo: [IMG_X + 204, IMG_Y + 609], caixa: "dir", y: 601 },
    { regiao: "Joelho Esquerdo", corpo: [IMG_X + 161, IMG_Y + 617], caixa: "esq", y: 609 },
    { regiao: "Tornozelo Direito", corpo: [IMG_X + 204, IMG_Y + 787], caixa: "dir", y: 779 },
    { regiao: "Tornozelo Esquerdo", corpo: [IMG_X + 165, IMG_Y + 791], caixa: "esq", y: 783 },
  ];

  const X_CENTRO = (IMG_X + IMG_W / 2) - LARGURA_CAIXA / 2;

  // ------------------------------------------------------------------
  // Base visual: imagem anatomica real (licenciada), com sombra suave para
  // integrar ao card. Sem filtro de cor - a foto mantem sua paleta propria
  // em tema claro e escuro (fundo do card e que muda).
  // ------------------------------------------------------------------
  function defsComuns(id) {
    return `
      <filter id="sombra-${id}" x="-20%" y="-20%" width="140%" height="140%">
        <feDropShadow dx="0" dy="3" stdDeviation="5" flood-color="#000000" flood-opacity="0.28" />
      </filter>
    `;
  }

  function imagemBase(id, ehCostas) {
    const href = ehCostas ? IMG_COSTAS : IMG_FRENTE;
    return `
      <image href="${href}" x="${IMG_X}" y="${IMG_Y}" width="${IMG_W}" height="${IMG_H}"
             filter="url(#sombra-${id})" preserveAspectRatio="xMidYMid meet" />
    `;
  }

  function caixaRotulo(item, valor, formatarValor) {
    const [px, py] = item.corpo;
    let bx;
    if (item.caixa === "esq") bx = X_COLUNA_ESQ;
    else if (item.caixa === "dir") bx = X_COLUNA_DIR;
    else bx = X_CENTRO;
    const by = item.y;
    const pontoLinhaX = item.caixa === "dir" ? bx : bx + LARGURA_CAIXA;
    const pontoLinhaY = by + ALTURA_CAIXA / 2;
    const destacar = valor > 0;

    return `
      <g class="bi-diagrama-regiao" data-regiao="${item.regiao}" tabindex="0" role="button"
         aria-label="${item.regiao}: ${formatarValor(valor)}">
        <line x1="${px}" y1="${py}" x2="${pontoLinhaX}" y2="${pontoLinhaY}"
              stroke="currentColor" stroke-width="1" stroke-dasharray="3 3" opacity="0.6" />
        <circle cx="${px}" cy="${py}" r="3.5" fill="currentColor" opacity="0.85" stroke="#fff" stroke-width="0.75" />
        <rect x="${bx}" y="${by}" width="${LARGURA_CAIXA}" height="${ALTURA_CAIXA}" rx="6"
              fill="var(--card)" stroke="currentColor" stroke-width="1" stroke-dasharray="3 3"
              opacity="${destacar ? 1 : 0.55}" />
        <text x="${bx + LARGURA_CAIXA / 2}" y="${by + 15}" text-anchor="middle"
              font-size="11" fill="currentColor" opacity="0.85">${item.regiao}</text>
        <text x="${bx + LARGURA_CAIXA / 2}" y="${by + 32}" text-anchor="middle"
              font-size="16" font-weight="700" fill="${destacar ? "var(--teal-escuro)" : "currentColor"}">${formatarValor(valor)}</text>
      </g>
    `;
  }

  function construirSvg(config, ehCostas, valoresPorRegiao, formatarValor, tituloAria, idUnico) {
    // Id unico por instancia (nao so "frente"/"costas") - varios diagramas
    // (Med Ocup + Compativeis) coexistem no mesmo documento (abas ocultas
    // com [hidden], nao removidas do DOM); ids <filter>/<defs> duplicados
    // quebram a resolucao de url(#...) em alguns motores de renderizacao.
    const id = idUnico || (ehCostas ? "costas" : "frente");
    const corpo = imagemBase(id, ehCostas);
    const caixas = config.map((item) => caixaRotulo(item, valoresPorRegiao[item.regiao] || 0, formatarValor)).join("");
    return `
      <svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${tituloAria}" style="width:100%;height:auto;color:var(--texto-secundario)">
        <defs>${defsComuns(id)}</defs>
        ${corpo}
        ${caixas}
      </svg>
    `;
  }

  function renderizar(containerId, tipo, valoresPorRegiao, opts) {
    const el = document.getElementById(containerId);
    if (!el) return;
    const config = tipo === "frente" ? CONFIG_FRENTE : CONFIG_COSTAS;
    const formatarValor = (opts && opts.formatarValor) || ((v) => String(v));
    const titulo = (opts && opts.titulo) || (tipo === "frente" ? "Diagrama corporal - vista frontal" : "Diagrama corporal - vista posterior");
    el.innerHTML = construirSvg(config, tipo === "costas", valoresPorRegiao, formatarValor, titulo, containerId);
  }

  global.BI = global.BI || {};
  global.BI.Diagramas = {
    CONFIG_FRENTE,
    CONFIG_COSTAS,
    renderizar,
  };
})(window);
